import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  CheckCircle2, 
  AlertCircle, 
  Clock, 
  ArrowRightLeft, 
  ShieldCheck, 
  FileText, 
  RefreshCw, 
  ExternalLink,
  Database,
  Zap
} from 'lucide-react';

/**
 * Custom hook for managing Citi-Alpaca Bridge operations.
 * Provides state management for synchronization records and execution handlers.
 */
export const useCitiAlpacaBridge = (accountId: string) => {
  const [records, setRecords] = useState<CitiAlpacaSyncRecord[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);

  const fetchRecords = useCallback(async () => {
    if (!accountId) return;
    setIsLoading(true);
    setError(null);
    try {
      const data = await citiAlpacaBridgeService.getSyncRecords(accountId);
      setRecords(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch bridge records');
    } finally {
      setIsLoading(false);
    }
  }, [accountId]);

  const initiateTransfer = async (amount: string, consentId: string) => {
    setIsProcessing(true);
    setError(null);
    try {
      const result = await citiAlpacaBridgeService.executeCitiToAlpacaIso20022Wire(
        accountId,
        amount,
        consentId
      );
      await fetchRecords();
      return result;
    } catch (err: any) {
      setError(err.message || 'Transfer execution failed');
      throw err;
    } finally {
      setIsProcessing(false);
    }
  };

  useEffect(() => {
    fetchRecords();
  }, [fetchRecords]);

  return {
    records,
    isLoading,
    isProcessing,
    error,
    refresh: fetchRecords,
    initiateTransfer
  };
};

