/**
 * @constant BRIDGE_CONFIG
 * Production-grade configuration for the Citi-Alpaca Bridge.
 * Includes retry policies, timeout settings, and ISO 20022 compliance flags.
 */
export const BRIDGE_CONFIG = {
  VERSION: '2.1.0',
  DEFAULT_CURRENCY: 'USD',
  SUPPORTED_ISO_MESSAGES: ['pacs.008.001.08', 'pacs.009.001.08'] as const,
  RETRY_LIMIT: 5,
  RETRY_DELAY_MS: 1000,
  OMNIBUS_ACCOUNT_ID: 'CITI_TREASURY_CORRESPONDENT_OMNIBUS',
  SETTLEMENT_TIMEOUT_MS: 86400000, // 24 hours
  ENABLE_STRICT_VALIDATION: true,
  LOG_LEVEL: 'verbose' as const,
};

/**
 * @enum BridgeStatus
 * Represents the lifecycle of a cross-institutional transfer.
 */
export enum BridgeStatus {
  PENDING = 'PENDING',
  INITIATED = 'INITIATED',
  IN_TRANSIT = 'IN_TRANSIT',
  SETTLED = 'SETTLED',
  FAILED = 'FAILED',
  REVERSED = 'REVERSED',
  PARTIALLY_SETTLED = 'PARTIALLY_SETTLED'
}

/**
 * @enum IsoMessageType
 * ISO 20022 Message Definitions for Financial Institutions.
 */
export enum IsoMessageType {
  CREDIT_TRANSFER = 'pacs.008.001.08',
  FINANCIAL_INSTITUTION_CREDIT_TRANSFER = 'pacs.009.001.08',
  CASH_MANAGEMENT_STATUS = 'camt.054.001.08'
}

/**
 * @interface CitiAlpacaSyncRecord
 * The primary data model for tracking bridge transactions.
 */
export interface CitiAlpacaSyncRecord {
  id: string;
  citi_wire_reference: string;
  citi_consent_id: string;
  amount: string;
  currency: string;
  alpaca_account_id: string;
  alpaca_journal_id: string;
  iso20022_message_type: IsoMessageType | string;
  status: BridgeStatus;
  timestamp: string;
  updated_at: string;
  error_message?: string;
  metadata?: {
    instruction_priority?: 'HIGH' | 'NORMAL';
    clearing_system?: 'CHIPS' | 'FEDWIRE' | 'SWIFT';
    remittance_info?: string;
    debtor_agent_bic?: string;
    creditor_agent_bic?: string;
  };
  retry_count: number;
  audit_trail: Array<{
    status: BridgeStatus;
    timestamp: string;
    reason?: string;
  }>;
}

/**
 * @interface BridgeStateStore
 * Interface for the internal state management of the bridge service.
 */
export interface BridgeStateStore {
  records: Map<string, CitiAlpacaSyncRecord[]>;
  indexByWireRef: Map<string, string>; // wire_ref -> record_id
  metrics: {
    total_processed_count: number;
    total_volume_usd: number;
    failure_count: number;
    last_sync_time: string | null;
  };
}

/**
 * @type BridgeEventPayload
 * Type definition for events emitted by the bridge.
 */
export type BridgeEventPayload = {
  recordId: string;
  status: BridgeStatus;
  timestamp: string;
  payload: Partial<CitiAlpacaSyncRecord>;
};

/**
 * Zod Schemas for Runtime Validation
 * Ensures all incoming data from Citi Open Banking FAPI or Alpaca Webhooks
 * adheres to strict financial data standards.
 */
export const WireTransferSchema = z.object({
  accountId: z.string().uuid({ message: "Invalid Alpaca Account ID format" }),
  amountUSD: z.string().refine((val) => !isNaN(parseFloat(val)) && parseFloat(val) > 0, {
    message: "Amount must be a positive numeric string",
  }),
  citiConsentId: z.string().min(10, { message: "Citi Consent ID is too short" }),
  messageType: z.nativeEnum(IsoMessageType).default(IsoMessageType.CREDIT_TRANSFER),
  metadata: z.record(z.any()).optional(),
});

export const SyncRecordValidator = z.object({
  id: z.string().uuid(),
  citi_wire_reference: z.string(),
  citi_consent_id: z.string(),
  amount: z.string(),
  currency: z.string().length(3),
  alpaca_account_id: z.string().uuid(),
  alpaca_journal_id: z.string(),
  iso20022_message_type: z.string(),
  status: z.nativeEnum(BridgeStatus),
  timestamp: z.string().datetime(),
  updated_at: z.string().datetime(),
  retry_count: z.number().int().min(0),
});

/**
 * @class BridgeEventEmitter
 * Custom emitter for real-time bridge monitoring and logging.
 */
export class BridgeEventEmitter extends EventEmitter {
  emitStatusChange(payload: BridgeEventPayload) {
    this.emit('status_change', payload);
  }
  emitError(error: Error, context: any) {
    this.emit('bridge_error', { error, context, timestamp: new Date().toISOString() });
  }
}

